<?php
declare(strict_types=1);

function match_route(string $method, string $path, string $verb, string $pattern): ?array {
    if ($method !== $verb) return null;
    $regex = preg_replace('/\{([A-Za-z][A-Za-z0-9_]*)\}/', '(?P<$1>[^/]+)', $pattern);
    if (!preg_match('#^' . $regex . '$#', $path, $m)) return null;
    return array_filter($m, 'is_string', ARRAY_FILTER_USE_KEY);
}
function require_fields(array $data, array $fields): void {
    foreach ($fields as $f) if (!isset($data[$f]) || $data[$f] === '') api_error("الحقل $f مطلوب", 400, 'VALIDATION_ERROR');
}
function user_public(array $u): array {
    foreach (['isActive','passwordAvailable'] as $k) if (isset($u[$k])) $u[$k] = (bool)$u[$k];
    return $u;
}
function user_by_id(string $id): ?array {
    return query_one('SELECT id, login_id AS loginId, full_name AS fullName, role, email, mobile, address, age, joined_at AS joinedAt, is_active AS isActive, created_at AS createdAt FROM users WHERE id=?', [$id]);
}
function halaqah_by_id(string $id): ?array {
    $h = query_one('SELECT h.id,h.name,h.teacher_id AS teacherId,u.id AS tId,u.login_id AS tLoginId,u.full_name AS tFullName FROM halaqahs h LEFT JOIN users u ON u.id=h.teacher_id WHERE h.id=?',[$id]);
    if (!$h) return null;
    $teacher = $h['tId'] ? ['id'=>$h['tId'],'loginId'=>$h['tLoginId'],'fullName'=>$h['tFullName']] : null;
    unset($h['tId'],$h['tLoginId'],$h['tFullName']);
    $h['teacher']=$teacher;
    return $h;
}
function all_halaqahs(): array {
    $rows=query_all('SELECT h.id,h.name,h.teacher_id AS teacherId,u.id AS tId,u.login_id AS tLoginId,u.full_name AS tFullName,(SELECT COUNT(*) FROM students s WHERE s.halaqah_id=h.id) AS studentCount FROM halaqahs h LEFT JOIN users u ON u.id=h.teacher_id ORDER BY h.name');
    return array_map(function($h){
        $h['teacher']=$h['tId']?['id'=>$h['tId'],'loginId'=>$h['tLoginId'],'fullName'=>$h['tFullName']]:null;
        $h['_count']=['students'=>(int)$h['studentCount']];
        unset($h['tId'],$h['tLoginId'],$h['tFullName'],$h['studentCount']);
        return $h;
    },$rows);
}
function period_rows(): array {
    $rows=query_all('SELECT id,number,name,start_time AS startTime,end_time AS endTime FROM schedule_periods ORDER BY number');
    foreach($rows as &$r)$r['number']=(int)$r['number']; return $rows;
}
function student_option_rows(string $where='1=1', array $params=[]): array {
    $sql="SELECT s.id,u.id AS userId,u.login_id AS loginId,u.full_name AS fullName,u.is_active AS userActive,
      h.id AS halaqahId,h.name AS halaqahName,t.id AS teacherId,t.full_name AS teacherName,
      d.building,d.room
      FROM students s JOIN users u ON u.id=s.user_id JOIN halaqahs h ON h.id=s.halaqah_id
      LEFT JOIN users t ON t.id=h.teacher_id LEFT JOIN dormitory_assignments d ON d.student_id=s.id
      WHERE $where ORDER BY u.full_name";
    return array_map(function($r){
        return ['id'=>$r['id'],'user'=>['id'=>$r['userId'],'loginId'=>$r['loginId'],'fullName'=>$r['fullName'],'isActive'=>(bool)$r['userActive']],
          'halaqah'=>['id'=>$r['halaqahId'],'name'=>$r['halaqahName'],'teacher'=>$r['teacherId']?['id'=>$r['teacherId'],'fullName'=>$r['teacherName']]:null],
          'dormitory'=>$r['building']!==null?['building'=>$r['building'],'room'=>$r['room']]:null];
    },query_all($sql,$params));
}
function progress_rows(string $where='1=1', array $params=[]): array {
    $sql="SELECT p.*, su.id AS studentUserId,su.login_id AS studentLoginId,su.full_name AS studentName,
      h.id AS halaqahId,h.name AS halaqahName,tu.id AS teacherUserId,tu.login_id AS teacherLoginId,tu.full_name AS teacherName,
      sp.number AS periodNumber,sp.name AS periodName,sp.start_time AS periodStart,sp.end_time AS periodEnd
      FROM progress_entries p JOIN students s ON s.id=p.student_id JOIN users su ON su.id=s.user_id
      JOIN halaqahs h ON h.id=s.halaqah_id JOIN users tu ON tu.id=p.teacher_id JOIN schedule_periods sp ON sp.id=p.period_id
      WHERE $where ORDER BY p.record_date DESC,p.created_at DESC LIMIT 500";
    $rows=query_all($sql,$params);
    return array_map(function($r){
        return [
          'id'=>$r['id'],'attended'=>(bool)$r['attended'],'recordType'=>$r['record_type'],'surah'=>$r['surah'],
          'verseFrom'=>$r['verse_from']===null?null:(int)$r['verse_from'],'endSurah'=>$r['end_surah'],'verseTo'=>$r['verse_to']===null?null:(int)$r['verse_to'],
          'matnName'=>$r['matn_name'],'matnFrom'=>$r['matn_from'],'matnTo'=>$r['matn_to'],'pages'=>(string)$r['pages'],
          'rating'=>$r['rating']===null?null:(int)$r['rating'],'recordDate'=>$r['record_date'],'note'=>$r['note'],'createdAt'=>$r['created_at'],
          'student'=>['id'=>$r['student_id'],'user'=>['id'=>$r['studentUserId'],'fullName'=>$r['studentName'],'loginId'=>$r['studentLoginId']],
            'halaqah'=>['id'=>$r['halaqahId'],'name'=>$r['halaqahName']]],
          'teacher'=>['id'=>$r['teacherUserId'],'fullName'=>$r['teacherName'],'loginId'=>$r['teacherLoginId']],
          'period'=>['id'=>$r['period_id'],'number'=>(int)$r['periodNumber'],'name'=>$r['periodName'],'startTime'=>$r['periodStart'],'endTime'=>$r['periodEnd']]
        ];
    },$rows);
}
function test_rows(string $where='1=1', array $params=[]): array {
    $sql="SELECT mt.*,s.user_id AS studentUserId,su.login_id AS studentLoginId,su.full_name AS studentName,
      eu.login_id AS examinerLoginId,eu.full_name AS examinerName,h.name AS halaqahName
      FROM monthly_tests mt JOIN students s ON s.id=mt.student_id JOIN users su ON su.id=s.user_id
      JOIN users eu ON eu.id=mt.examiner_id JOIN halaqahs h ON h.id=mt.halaqah_id
      WHERE $where ORDER BY mt.test_date DESC,mt.created_at DESC LIMIT 200";
    $rows=query_all($sql,$params);
    foreach($rows as &$r){
        $qs=query_all('SELECT id,question_number AS questionNumber,correct,surah,ayah,ayah_to AS ayahTo,reference_text AS referenceText FROM monthly_test_questions WHERE monthly_test_id=? ORDER BY question_number',[$r['id']]);
        foreach($qs as &$q){$q['questionNumber']=(int)$q['questionNumber'];$q['correct']=(bool)$q['correct'];$q['ayah']=$q['ayah']===null?null:(int)$q['ayah'];$q['ayahTo']=$q['ayahTo']===null?null:(int)$q['ayahTo'];}
        $r=['id'=>$r['id'],'type'=>$r['type'],'matnName'=>$r['matn_name'],'score'=>(int)$r['score'],'note'=>$r['note'],'testDate'=>$r['test_date'],'createdAt'=>$r['created_at'],
          'student'=>['id'=>$r['student_id'],'user'=>['id'=>$r['studentUserId'],'loginId'=>$r['studentLoginId'],'fullName'=>$r['studentName']]],
          'examiner'=>['id'=>$r['examiner_id'],'loginId'=>$r['examinerLoginId'],'fullName'=>$r['examinerName']],
          'halaqah'=>['id'=>$r['halaqah_id'],'name'=>$r['halaqahName']],'questions'=>$qs];
    } unset($r);
    return $rows;
}
function report_access_where(array $u, string $studentId): array {
    if ($u['role']==='TEACHER') return ['s.id=? AND h.teacher_id=?',[$studentId,$u['id']]];
    if ($u['role']==='STUDENT') return ['s.id=? AND s.user_id=?',[$studentId,$u['id']]];
    if ($u['role']==='PARENT') return ['s.id=? AND EXISTS(SELECT 1 FROM parent_students ps WHERE ps.student_id=s.id AND ps.parent_id=?)',[$studentId,$u['id']]];
    return ['s.id=?',[$studentId]];
}
function student_report(string $studentId, array $actor, ?string $from, ?string $to): array {
    $to=$to?:gmdate('Y-m-d'); $from=$from?:gmdate('Y-m-d',strtotime($to.' -29 days'));
    if(strtotime($from)===false||strtotime($to)===false||$from>$to) api_error('نطاق تاريخ التقرير غير صالح',400,'INVALID_REPORT_RANGE');
    [$aw,$ap]=report_access_where($actor,$studentId);
    $s=query_one("SELECT s.id,s.memorized_amount AS memorizedAmount,u.id AS userId,u.login_id AS loginId,u.full_name AS fullName,u.email,u.mobile,u.age,u.joined_at AS joinedAt,u.is_active AS isActive,h.id AS halaqahId,h.name AS halaqahName,t.id AS teacherId,t.login_id AS teacherLoginId,t.full_name AS teacherName,d.building,d.room FROM students s JOIN users u ON u.id=s.user_id JOIN halaqahs h ON h.id=s.halaqah_id LEFT JOIN users t ON t.id=h.teacher_id LEFT JOIN dormitory_assignments d ON d.student_id=s.id WHERE $aw",$ap);
    if(!$s) api_error('ليس لديك صلاحية لعرض تقرير هذا الطالب',403,'STUDENT_REPORT_FORBIDDEN');
    $progress=progress_rows('p.student_id=? AND p.record_date BETWEEN ? AND ?',[$studentId,$from,$to]);
    $tests=test_rows('mt.student_id=? AND mt.test_date BETWEEN ? AND ?',[$studentId,$from,$to]);
    $duration=max(1,strtotime($to)-strtotime($from)); $prevTo=gmdate('Y-m-d',strtotime($from)-86400); $prevFrom=gmdate('Y-m-d',strtotime($prevTo)-$duration);
    $prevP=progress_rows('p.student_id=? AND p.record_date BETWEEN ? AND ?',[$studentId,$prevFrom,$prevTo]);
    $prevT=test_rows('mt.student_id=? AND mt.test_date BETWEEN ? AND ?',[$studentId,$prevFrom,$prevTo]);
    $avg=function(array $vals){$v=array_values(array_filter($vals,fn($x)=>$x!==null));return count($v)?array_sum($v)/count($v):0;};
    $att=count(array_filter($progress,fn($x)=>$x['attended'])); $ratings=array_map(fn($x)=>$x['attended']?$x['rating']:null,$progress);
    $curR=$avg($ratings);$prevR=$avg(array_map(fn($x)=>$x['attended']?$x['rating']:null,$prevP));$curT=$avg(array_column($tests,'score'));$prevTs=$avg(array_column($prevT,'score'));
    $trend=function($c,$p,$tol=.15){if(!$c&&!$p)return'NO_DATA';if(!$p)return'NEW_DATA';$d=$c-$p;return$d>$tol?'IMPROVING':($d<-$tol?'DECLINING':'STABLE');};
    $types=[];foreach(['HIFZ','NEAR_REVIEW','FAR_REVIEW','MATN'] as $type){$r=array_values(array_filter($progress,fn($x)=>$x['attended']&&$x['recordType']===$type));$types[$type]=['count'=>count($r),'averageRating'=>$avg(array_column($r,'rating')),'pages'=>array_sum(array_map(fn($x)=>(float)$x['pages'],$r))];}
    return ['student'=>['id'=>$s['id'],'memorizedAmount'=>$s['memorizedAmount'],'user'=>['id'=>$s['userId'],'loginId'=>$s['loginId'],'fullName'=>$s['fullName'],'email'=>$s['email'],'mobile'=>$s['mobile'],'age'=>$s['age']===null?null:(int)$s['age'],'joinedAt'=>$s['joinedAt'],'isActive'=>(bool)$s['isActive']],
      'halaqah'=>['id'=>$s['halaqahId'],'name'=>$s['halaqahName'],'teacher'=>$s['teacherId']?['id'=>$s['teacherId'],'loginId'=>$s['teacherLoginId'],'fullName'=>$s['teacherName']]:null],
      'dormitory'=>$s['building']!==null?['building'=>$s['building'],'room'=>$s['room']]:null],
      'period'=>['from'=>$from,'to'=>$to,'previousFrom'=>$prevFrom,'previousTo'=>$prevTo],
      'summary'=>['sessions'=>count($progress),'attended'=>$att,'absent'=>count($progress)-$att,'attendanceRate'=>count($progress)?$att/count($progress)*100:0,'totalPages'=>array_sum(array_map(fn($x)=>(float)$x['pages'],$progress)),'averageRating'=>$curR,'tests'=>count($tests),'averageTestScore'=>$curT,'latestTestScore'=>$tests[0]['score']??null,'recordTypes'=>$types],
      'trend'=>['rating'=>['current'=>$curR,'previous'=>$prevR,'direction'=>$trend($curR,$prevR)],'tests'=>['current'=>$curT,'previous'=>$prevTs,'direction'=>$trend($curT,$prevTs,3)]],
      'progress'=>$progress,'tests'=>$tests];
}
function save_raw_upload(string $folder): array {
    $name=urldecode($_SERVER['HTTP_X_FILE_NAME']??'file.bin');
    $name=preg_replace('/[^A-Za-z0-9._-]+/u','_',basename($name))?:'file.bin';
    $ext=pathinfo($name,PATHINFO_EXTENSION); $stored=bin2hex(random_bytes(12)).($ext?'.'.$ext:'');
    $dir=dirname(__DIR__).'/public/uploads/'.$folder; if(!is_dir($dir))mkdir($dir,0775,true);
    file_put_contents($dir.'/'.$stored,file_get_contents('php://input'));
    $mime=$_SERVER['CONTENT_TYPE']??'application/octet-stream';
    return ['url'=>'/uploads/'.$folder.'/'.$stored,'fileName'=>$name,'mimeType'=>$mime];
}
function managed_users(array $actor): array {
    $where=$actor['role']==='MANAGER'?"WHERE u.role IN ('TEACHER','STUDENT','PARENT')":'';
    $rows=query_all("SELECT u.id,u.login_id AS loginId,u.full_name AS fullName,u.role,u.email,u.mobile,u.address,u.age,u.joined_at AS joinedAt,u.is_active AS isActive,u.created_at AS createdAt,(u.credential_ciphertext IS NOT NULL) AS passwordAvailable,s.id AS studentId,s.memorized_amount AS memorizedAmount,h.id AS halaqahId,h.name AS halaqahName,d.building,d.room FROM users u LEFT JOIN students s ON s.user_id=u.id LEFT JOIN halaqahs h ON h.id=s.halaqah_id LEFT JOIN dormitory_assignments d ON d.student_id=s.id $where ORDER BY u.full_name");
    return array_map(function($r){$r['isActive']=(bool)$r['isActive'];$r['passwordAvailable']=(bool)$r['passwordAvailable'];$r['age']=$r['age']===null?null:(int)$r['age'];$r['studentProfile']=$r['studentId']?['halaqah'=>$r['halaqahId']?['id'=>$r['halaqahId'],'name'=>$r['halaqahName']]:null,'dormitory'=>$r['building']!==null?['building'=>$r['building'],'room'=>$r['room']]:null,'memorizedAmount'=>$r['memorizedAmount']]:null;unset($r['studentId'],$r['memorizedAmount'],$r['halaqahId'],$r['halaqahName'],$r['building'],$r['room']);return$r;},$rows);
}

function handle_api(string $method,string $path): never {
    if($path==='/api/health'&&$method==='GET') json_response(['status'=>'ok','service'=>'progress-tracker-api-php','database'=>'mysql']);

    if($path==='/api/auth/login'&&$method==='POST'){
        $in=body_json();require_fields($in,['loginId','password']);
        $u=query_one('SELECT id,login_id AS loginId,full_name AS fullName,password_hash AS passwordHash,role,is_active AS isActive FROM users WHERE login_id=?',[$in['loginId']]);
        if(!$u||!(bool)$u['isActive']||!password_matches((string)$in['password'],$u['passwordHash']))api_error('بيانات الدخول غير صحيحة',401,'INVALID_CREDENTIALS');
        json_response(['token'=>jwt_sign($u['id']),'user'=>['id'=>$u['id'],'loginId'=>$u['loginId'],'fullName'=>$u['fullName'],'role'=>$u['role']],'dashboardReady'=>true]);
    }
    if($path==='/api/auth/me'&&$method==='GET'){ $u=current_user(); json_response(['user'=>['id'=>$u['id'],'loginId'=>$u['loginId'],'fullName'=>$u['fullName'],'role'=>$u['role']],'dashboardReady'=>true]); }

    if($path==='/api/content/home'&&$method==='GET'){
        $h=query_one('SELECT id,eyebrow,hero_title AS heroTitle,hero_body AS heroBody,about_title AS aboutTitle,about_body AS aboutBody,feature1_title AS feature1Title,feature1_body AS feature1Body,feature2_title AS feature2Title,feature2_body AS feature2Body,feature3_title AS feature3Title,feature3_body AS feature3Body,callout_title AS calloutTitle,callout_body AS calloutBody,footer_phone AS footerPhone,footer_email AS footerEmail,footer_instagram AS footerInstagram,footer_facebook AS footerFacebook FROM home_page_content WHERE id="home"');
        json_response(['home'=>$h]);
    }
    if($path==='/api/content/library'&&$method==='GET'){ $rows=query_all('SELECT id,title,description,type,url,cover_url AS coverUrl,published,created_at AS createdAt,updated_at AS updatedAt FROM library_items WHERE published=1 ORDER BY created_at DESC');foreach($rows as &$r)$r['published']=(bool)$r['published'];json_response(['items'=>$rows]);}
    if($path==='/api/content/media'&&$method==='GET'){ $rows=query_all('SELECT a.id,a.title,a.content,a.category,a.image_url AS imageUrl,a.published,a.created_at AS createdAt,a.updated_at AS updatedAt,u.id AS authorId,u.full_name AS authorName FROM activities a JOIN users u ON u.id=a.author_id WHERE a.published=1 ORDER BY a.created_at DESC'); foreach($rows as &$r){$r['published']=(bool)$r['published'];$r['author']=['id'=>$r['authorId'],'fullName'=>$r['authorName']];unset($r['authorId'],$r['authorName']);$r['assets']=query_all('SELECT id,kind,mime_type AS mimeType,file_name AS fileName,url,sort_order AS sortOrder,created_at AS createdAt FROM activity_assets WHERE activity_id=? ORDER BY sort_order,created_at',[$r['id']]);}json_response(['activities'=>$rows]);}

    if($path==='/api/content/library/manage'&&$method==='GET'){require_role(['ADMIN','MANAGER']);$rows=query_all('SELECT id,title,description,type,url,cover_url AS coverUrl,published,created_at AS createdAt,updated_at AS updatedAt FROM library_items ORDER BY created_at DESC');foreach($rows as &$r)$r['published']=(bool)$r['published'];json_response(['items'=>$rows]);}
    if($path==='/api/content/media/manage'&&$method==='GET'){require_role(['ADMIN','MANAGER']);$rows=query_all('SELECT a.id,a.title,a.content,a.category,a.image_url AS imageUrl,a.published,a.created_at AS createdAt,a.updated_at AS updatedAt,u.id AS authorId,u.full_name AS authorName FROM activities a JOIN users u ON u.id=a.author_id ORDER BY a.created_at DESC');foreach($rows as &$r){$r['published']=(bool)$r['published'];$r['author']=['id'=>$r['authorId'],'fullName'=>$r['authorName']];unset($r['authorId'],$r['authorName']);$r['assets']=query_all('SELECT id,kind,mime_type AS mimeType,file_name AS fileName,url,sort_order AS sortOrder,created_at AS createdAt FROM activity_assets WHERE activity_id=? ORDER BY sort_order,created_at',[$r['id']]);}json_response(['activities'=>$rows]);}
    if($path==='/api/content/home'&&$method==='PUT'){require_role(['ADMIN']);$in=body_json();$fields=['eyebrow','heroTitle','heroBody','aboutTitle','aboutBody','feature1Title','feature1Body','feature2Title','feature2Body','feature3Title','feature3Body','calloutTitle','calloutBody'];require_fields($in,$fields);execute_sql('UPDATE home_page_content SET eyebrow=?,hero_title=?,hero_body=?,about_title=?,about_body=?,feature1_title=?,feature1_body=?,feature2_title=?,feature2_body=?,feature3_title=?,feature3_body=?,callout_title=?,callout_body=?,footer_phone=?,footer_email=?,footer_instagram=?,footer_facebook=? WHERE id="home"',[$in['eyebrow'],$in['heroTitle'],$in['heroBody'],$in['aboutTitle'],$in['aboutBody'],$in['feature1Title'],$in['feature1Body'],$in['feature2Title'],$in['feature2Body'],$in['feature3Title'],$in['feature3Body'],$in['calloutTitle'],$in['calloutBody'],$in['footerPhone']??null,$in['footerEmail']??null,$in['footerInstagram']??null,$in['footerFacebook']??null]);$h=query_one('SELECT id,eyebrow,hero_title AS heroTitle,hero_body AS heroBody,about_title AS aboutTitle,about_body AS aboutBody,feature1_title AS feature1Title,feature1_body AS feature1Body,feature2_title AS feature2Title,feature2_body AS feature2Body,feature3_title AS feature3Title,feature3_body AS feature3Body,callout_title AS calloutTitle,callout_body AS calloutBody,footer_phone AS footerPhone,footer_email AS footerEmail,footer_instagram AS footerInstagram,footer_facebook AS footerFacebook FROM home_page_content WHERE id="home"');json_response(['home'=>$h,'message'=>'تم تحديث الصفحة الرئيسية']);}
    if($path==='/api/content/library/upload'&&$method==='POST'){require_role(['ADMIN','MANAGER']);$f=save_raw_upload('library');$type=str_contains($f['mimeType'],'pdf')?'PDF':(str_contains($f['mimeType'],'image')?'IMAGE':'FILE');json_response(['file'=>$f+['type'=>$type],'message'=>'تم رفع الملف'],201);}
    if($path==='/api/content/library'&&$method==='POST'){require_role(['ADMIN','MANAGER']);$in=body_json();require_fields($in,['title','url']);$id=uid();execute_sql('INSERT INTO library_items(id,title,description,type,url,cover_url,published) VALUES(?,?,?,?,?,?,?)',[$id,$in['title'],$in['description']??null,$in['type']??'PDF',$in['url'],$in['coverUrl']??null,isset($in['published'])?(int)bool_value($in['published']):1]);$r=query_one('SELECT id,title,description,type,url,cover_url AS coverUrl,published,created_at AS createdAt,updated_at AS updatedAt FROM library_items WHERE id=?',[$id]);$r['published']=(bool)$r['published'];json_response(['item'=>$r,'message'=>'تمت إضافة مادة المكتبة'],201);}
    if($m=match_route($method,$path,'PATCH','/api/content/library/{id}')){require_role(['ADMIN','MANAGER']);$in=body_json();$old=query_one('SELECT * FROM library_items WHERE id=?',[$m['id']]);if(!$old)api_error('المادة غير موجودة',404,'NOT_FOUND');execute_sql('UPDATE library_items SET title=?,description=?,type=?,url=?,cover_url=?,published=? WHERE id=?',[$in['title']??$old['title'],$in['description']??$old['description'],$in['type']??$old['type'],$in['url']??$old['url'],array_key_exists('coverUrl',$in)?$in['coverUrl']:$old['cover_url'],array_key_exists('published',$in)?(int)bool_value($in['published']):$old['published'],$m['id']]);$r=query_one('SELECT id,title,description,type,url,cover_url AS coverUrl,published,created_at AS createdAt,updated_at AS updatedAt FROM library_items WHERE id=?',[$m['id']]);$r['published']=(bool)$r['published'];json_response(['item'=>$r,'message'=>'تم تحديث مادة المكتبة']);}
