    if($path==='/api/operations/notes'&&$method==='GET'){$u=require_role(['ADMIN','MANAGER','TEACHER']);$w=$u['role']==='TEACHER'?'(nv.author_id=? OR EXISTS(SELECT 1 FROM students s JOIN halaqahs h ON h.id=s.halaqah_id WHERE s.user_id=nv.subject_user_id AND h.teacher_id=?))':'1=1';$p=$u['role']==='TEACHER'?[$u['id'],$u['id']]:[];$rows=query_all("SELECT nv.*,s.login_id AS subjectLogin,s.full_name AS subjectName,s.role AS subjectRole,a.login_id AS authorLogin,a.full_name AS authorName,a.role AS authorRole,h.name AS halaqahName FROM notes_violations nv JOIN users s ON s.id=nv.subject_user_id JOIN users a ON a.id=nv.author_id LEFT JOIN halaqahs h ON h.id=nv.halaqah_id WHERE $w ORDER BY nv.created_at DESC",$p);$notes=array_map(fn($r)=>['id'=>$r['id'],'kind'=>$r['kind'],'context'=>$r['context'],'content'=>$r['content'],'createdAt'=>$r['created_at'],'subject'=>['id'=>$r['subject_user_id'],'loginId'=>$r['subjectLogin'],'fullName'=>$r['subjectName'],'role'=>$r['subjectRole']],'author'=>['id'=>$r['author_id'],'loginId'=>$r['authorLogin'],'fullName'=>$r['authorName'],'role'=>$r['authorRole']],'halaqah'=>$r['halaqah_id']?['id'=>$r['halaqah_id'],'name'=>$r['halaqahName']]:null],$rows);json_response(['notes'=>$notes]);}
