    if($path==='/api/operations/monthly-tests'&&$method==='POST'){$u=require_role(['ADMIN','TEACHER']);$in=body_json();require_fields($in,['studentId','type','score','testDate']);$s=query_one('SELECT s.id,s.halaqah_id AS halaqahId,h.teacher_id AS teacherId FROM students s JOIN halaqahs h ON h.id=s.halaqah_id WHERE s.id=?',[$in['studentId']]);if(!$s)api_error('الطالب غير موجود',404,'STUDENT_NOT_FOUND');if($u['role']==='TEACHER'&&$s['teacherId']!==$u['id'])api_error('لا يمكنك اختبار هذا الطالب',403,'FORBIDDEN');$id=uid();db()->beginTransaction();try{execute_sql('INSERT INTO monthly_tests(id,student_id,examiner_id,halaqah_id,type,matn_name,score,note,test_date) VALUES(?,?,?,?,?,?,?,?,?)',[$id,$in['studentId'],$u['id'],$s['halaqahId'],$in['type'],$in['matnName']??null,(int)$in['score'],$in['note']??null,$in['testDate']]);foreach(($in['questions']??[]) as $q)execute_sql('INSERT INTO monthly_test_questions(id,monthly_test_id,question_number,correct,surah,ayah,ayah_to,reference_text) VALUES(?,?,?,?,?,?,?,?)',[uid(),$id,(int)$q['questionNumber'],(int)bool_value($q['correct']??false),$q['surah']??null,$q['ayah']??null,$q['ayahTo']??null,$q['referenceText']??null]);db()->commit();}catch(Throwable $e){db()->rollBack();throw$e;}json_response(['test'=>test_rows('mt.id=?',[$id])[0],'message'=>'تم حفظ الاختبار الشهري'],201);}
