    if($path==='/api/reports/students'&&$method==='GET'){$u=current_user();$where='1=1';$p=[];if($u['role']==='TEACHER'){$where='h.teacher_id=?';$p=[$u['id']];}elseif($u['role']==='STUDENT'){$where='s.user_id=?';$p=[$u['id']];}elseif($u['role']==='PARENT'){$where='EXISTS(SELECT 1 FROM parent_students ps WHERE ps.student_id=s.id AND ps.parent_id=?)';$p=[$u['id']];}$rows=query_all("SELECT s.id,s.memorized_amount AS memorizedAmount,u.id AS userId,u.login_id AS loginId,u.full_name AS fullName,u.email,u.mobile,u.age,u.joined_at AS joinedAt,u.is_active AS isActive,h.id AS halaqahId,h.name AS halaqahName,t.id AS teacherId,t.login_id AS teacherLoginId,t.full_name AS teacherName,d.building,d.room FROM students s JOIN users u ON u.id=s.user_id JOIN halaqahs h ON h.id=s.halaqah_id LEFT JOIN users t ON t.id=h.teacher_id LEFT JOIN dormitory_assignments d ON d.student_id=s.id WHERE $where ORDER BY u.full_name",$p);$out=array_map(fn($r)=>['id'=>$r['id'],'memorizedAmount'=>$r['memorizedAmount'],'user'=>['id'=>$r['userId'],'loginId'=>$r['loginId'],'fullName'=>$r['fullName'],'email'=>$r['email'],'mobile'=>$r['mobile'],'age'=>$r['age']===null?null:(int)$r['age'],'joinedAt'=>$r['joinedAt'],'isActive'=>(bool)$r['isActive']],'halaqah'=>['id'=>$r['halaqahId'],'name'=>$r['halaqahName'],'teacher'=>$r['teacherId']?['id'=>$r['teacherId'],'loginId'=>$r['teacherLoginId'],'fullName'=>$r['teacherName']]:null],'dormitory'=>$r['building']!==null?['building'=>$r['building'],'room'=>$r['room']]:null],$rows);json_response(['students'=>$out]);}
