    if($path==='/api/ai/analyze'&&$method==='POST'){require_role(['ADMIN']);$in=body_json();require_fields($in,['userId']);$person=query_one('SELECT id,login_id AS loginId,full_name AS fullName,role FROM users WHERE id=?',[$in['userId']]);if(!$person)api_error('الحساب المحدد غير موجود',404,'AI_PERSON_NOT_FOUND');$context=['subject'=>$person,'period'=>['from'=>$in['from']??gmdate('Y-m-d',strtotime('-29 days')),'to'=>$in['to']??gmdate('Y-m-d')]];$s=query_one('SELECT id FROM students WHERE user_id=?',[$person['id']]);if($s)$context['studentReport']=student_report($s['id'],['id'=>$person['id'],'role'=>'ADMIN'],$in['from']??null,$in['to']??null);$prompt=['model'=>config()['LOCAL_AI_MODEL'],'stream'=>false,'messages'=>[['role'=>'system','content'=>'Respond in professional Arabic. Use only the supplied institutional context. Return JSON with title, summary, trajectory(label, explanation), recommendations(title, reason, priority), evidence, limitations, answer.'],['role'=>'user','content'=>json_encode(['task'=>$in['question']??'حلل البيانات وقدّم توصيات عملية','context'=>$context,'previousAnswers'=>$in['previousAnswers']??[]],JSON_UNESCAPED_UNICODE)]],'format'=>'json','options'=>['temperature'=>0]];$opts=['http'=>['method'=>'POST','header'=>"Content-Type: application/json\r\n",'content'=>json_encode($prompt,JSON_UNESCAPED_UNICODE),'timeout'=>(int)config()['LOCAL_AI_TIMEOUT_SECONDS'],'ignore_errors'=>true]];$raw=@file_get_contents(rtrim(config()['LOCAL_AI_BASE_URL'],'/').'/api/chat',false,stream_context_create($opts));if($raw===false)api_error('تعذر الاتصال بخادم الذكاء الاصطناعي المحلي',503,'LOCAL_AI_UNAVAILABLE');$resp=json_decode($raw,true);$text=trim($resp['message']['content']??'');$analysis=json_decode($text,true);if(!is_array($analysis))api_error('تعذر قراءة نتيجة النموذج المحلي',502,'LOCAL_AI_INVALID_RESPONSE');json_response(['analysis'=>$analysis,'subject'=>$person,'period'=>$context['period'],'audience'=>$in['audience']??'ADMIN','model'=>config()['LOCAL_AI_MODEL'],'provider'=>'LOCAL']);}

